11	#include "torch_kernel_helper.h"
12	#include "aclrtlaunch_gather.h"
13	#include <torch/extension.h>
14	#include "tiling/platform/platform_ascendc.h"
15	
16	namespace ascend_kernel {
17	
18	constexpr int64_t MAX_CORES = 40;
19	
20	at::Tensor gather(const at::Tensor& self, int64_t dim, const at::Tensor& index, bool sparse_grad) {
21	    (void)sparse_grad;  // sparse_grad only affects backward, ignored in forward
22	
23	    // ---- Input validation ----
24	    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
25	                "gather: input must be on NPU device");
26	    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
27	                "gather: index must be on NPU device");
28	
29	    int64_t ndim = self.dim();
30	    int64_t dimVal = dim;
31	    if (dimVal < 0) dimVal += ndim;
32	
33	    TORCH_CHECK(dimVal >= 0 && dimVal < ndim,
34	                "gather: dim out of range, got dim=", dim);
35	    TORCH_CHECK(index.dim() == ndim,
36	                "gather: index must have same ndim as input");
37	
38	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
39	                self.scalar_type() == at::kHalf ||
40	                self.scalar_type() == at::kBFloat16,
41	                "gather: only float32, float16 and bfloat16 are supported");
42	
43	    // ---- Contiguous ----
44	    at::Tensor inputContiguous = self.contiguous();
45	    at::Tensor indexContiguous = index.contiguous();
46	
47	    // ---- Dimension params ----
48	    int64_t N = inputContiguous.size(dimVal);
49	    int64_t K = indexContiguous.size(dimVal);
50	    int64_t dtypeSize = inputContiguous.element_size();
51	
52	    // ---- Index to int32 ----
53	    auto indexInt32 = indexContiguous.to(at::kInt);
54	
55	    // ---- 3D dimension unification ----
56	    // transpose(dim, -1) moves dim to last dimension, then reshape to [batch, rows, N/K]
57	    int64_t batch = 1;
58	    for (int64_t i = 0; i < dimVal; i++) batch *= inputContiguous.size(i);
59	    int64_t rows = inputContiguous.numel() / (batch * N);
60	
61	    auto inputFlat = inputContiguous.transpose(dimVal, -1).contiguous()
62	                         .reshape({batch, rows, N});
63	    auto indexFlat = indexInt32.transpose(dimVal, -1).contiguous()
64	                         .reshape({batch, rows, K});
65	
66	    auto outputFlat = at::empty({batch, rows, K},
67	        inputContiguous.options().dtype(
68	            inputContiguous.scalar_type() == at::kBFloat16
69	                ? at::kBFloat16 : inputContiguous.scalar_type()));
70	
71	    // ---- Launch kernel ----
72	    int64_t totalRows = batch * rows;
73	    int64_t rowOffset = 0;
74	
75	    int64_t blockDimInt = totalRows < MAX_CORES ? totalRows : MAX_CORES;
76	    if (blockDimInt < 1) blockDimInt = 1;
77	    uint32_t blockDim = static_cast<uint32_t>(blockDimInt);
78	
79	    // All parameters must be lvalues for EXEC_KERNEL_CMD
80	    int64_t inputRowsVal = batch * rows;
81	    int64_t srcDimSizeVal = N;
82	    int64_t indexSizeVal = K;
83	    int64_t dtypeSizeVal = dtypeSize;
84	    int64_t totalRowsVal = totalRows;
85	    int64_t rowOffsetVal = rowOffset;
86	
87	    EXEC_KERNEL_CMD(gather, blockDim, inputFlat, indexFlat, outputFlat,
88	                    inputRowsVal, srcDimSizeVal, indexSizeVal, dtypeSizeVal,
89	                    totalRowsVal, rowOffsetVal);
90	
91	    // ---- Output reshape ----
92	    std::vector<int64_t> transposedOutShape;
93	    for (int64_t i = 0; i < ndim; i++) {
94	        if (i == dimVal) continue;
95	        transposedOutShape.push_back(indexContiguous.size(i));
96	    }
97	    transposedOutShape.push_back(K);
98	
99	    auto outputContiguous = outputFlat.reshape(transposedOutShape)
100	                                .transpose(ndim - 1, dimVal).contiguous();
101	
102	    return outputContiguous.reshape(index.sizes());
103	}
104	
105	}  // namespace ascend_kernel
