#include "torch_kernel_helper.h"
#include "aclrtlaunch_gather.h"
#include <torch/extension.h>
#include "tiling/platform/platform_ascendc.h"

namespace ascend_kernel {

constexpr int64_t MAX_CORES = 40;

at::Tensor gather(const at::Tensor& self, int64_t dim, const at::Tensor& index, bool sparse_grad) {
    (void)sparse_grad;  // sparse_grad only affects backward, ignored in forward

    // ---- Input validation ----
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "gather: input must be on NPU device");
    TORCH_CHECK(index.device().type() == at::DeviceType::PrivateUse1,
                "gather: index must be on NPU device");

    int64_t ndim = self.dim();
    int64_t dimVal = dim;
    if (dimVal < 0) dimVal += ndim;

    TORCH_CHECK(dimVal >= 0 && dimVal < ndim,
                "gather: dim out of range, got dim=", dim);
    TORCH_CHECK(index.dim() == ndim,
                "gather: index must have same ndim as input");

    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "gather: only float32, float16 and bfloat16 are supported");

    // ---- Contiguous ----
    at::Tensor inputContiguous = self.contiguous();
    at::Tensor indexContiguous = index.contiguous();

    // ---- Dimension params ----
    int64_t N = inputContiguous.size(dimVal);
    int64_t K = indexContiguous.size(dimVal);
    int64_t dtypeSize = inputContiguous.element_size();

    // ---- Index to int32 ----
    auto indexInt32 = indexContiguous.to(at::kInt);

    // ---- Compute strides for offset calculation ----
    // input strides (for original shape)
    std::vector<int64_t> inputStrides(ndim);
    inputStrides[ndim - 1] = 1;
    for (int64_t i = ndim - 2; i >= 0; i--) {
        inputStrides[i] = inputStrides[i + 1] * inputContiguous.size(i + 1);
    }

    // index strides (for original shape)
    std::vector<int64_t> indexStrides(ndim);
    indexStrides[ndim - 1] = 1;
    for (int64_t i = ndim - 2; i >= 0; i--) {
        indexStrides[i] = indexStrides[i + 1] * indexContiguous.size(i + 1);
    }

    // output strides (same as index)
    std::vector<int64_t> outputStrides = indexStrides;

    // ---- 3D dimension unification ----
    // transpose(dim, -1) moves dim to last dimension
    // For input: we need to handle cases where input and index have different shapes
    // We use index shape for batch/rows, and flatten input to match
    int64_t batch = 1;
    for (int64_t i = 0; i < dimVal; i++) batch *= indexContiguous.size(i);
    int64_t rows = indexContiguous.numel() / (batch * K);

    // For input, we need to create a view that has the right shape
    // input.transpose(dim, -1) gives shape where dim and last are swapped
    // Then we flatten to [batch * rows, N] for the kernel
    auto inputTransposed = inputContiguous.transpose(dimVal, -1).contiguous();
    auto inputFlat = inputTransposed.reshape({-1, N});

    auto indexTransposed = indexInt32.transpose(dimVal, -1).contiguous();
    auto indexFlat = indexTransposed.reshape({-1, K});

    auto outputFlat = at::empty({batch * rows, K},
        inputContiguous.options().dtype(
            inputContiguous.scalar_type() == at::kBFloat16
                ? at::kBFloat16 : inputContiguous.scalar_type()));

    // ---- Launch kernel ----
    int64_t totalRows = batch * rows;
    int64_t rowOffset = 0;

    int64_t blockDimInt = totalRows < MAX_CORES ? totalRows : MAX_CORES;
    if (blockDimInt < 1) blockDimInt = 1;
    uint32_t blockDim = static_cast<uint32_t>(blockDimInt);

    // All parameters must be lvalues for EXEC_KERNEL_CMD
    int64_t inputRowsVal = inputFlat.size(0);
    int64_t srcDimSizeVal = N;
    int64_t indexSizeVal = K;
    int64_t dtypeSizeVal = dtypeSize;
    int64_t totalRowsVal = totalRows;
    int64_t rowOffsetVal = rowOffset;

    EXEC_KERNEL_CMD(gather, blockDim, inputFlat, indexFlat, outputFlat,
                    inputRowsVal, srcDimSizeVal, indexSizeVal, dtypeSizeVal,
                    totalRowsVal, rowOffsetVal);

    // ---- Output reshape ----
    // outputFlat is [batch*rows, K]
    // Reshape to transposed shape: [batch, rows, K]
    // Then transpose back: swap last dim with dim
    auto outputTransposed = outputFlat.reshape({batch, rows, K});

    // transpose(ndim-1, dimVal) to move K back to its original position
    // But we need to handle the full ndim shape
    std::vector<int64_t> outShapeNd;
    for (int64_t i = 0; i < ndim; i++) {
        outShapeNd.push_back(indexContiguous.size(i));
    }

    // The transposed shape is: [d0, ..., d_{dim-1}, d_{ndim-1}, d_{dim+1}, ..., d_{ndim-2}, K]
    // We have [batch, rows, K] where batch = d0*...*d_{dim-1}, rows = d_{dim+1}*...*d_{ndim-1}
    // To get back to original shape [d0, ..., d_{dim-1}, K, d_{dim+1}, ..., d_{ndim-1}]:
    // First reshape [batch, rows, K] to [d0, ..., d_{dim-1}, d_{dim+1}, ..., d_{ndim-1}, K]
    // Then transpose dim and last

    std::vector<int64_t> transposedShape;
    for (int64_t i = 0; i < ndim; i++) {
        if (i == dimVal) continue;
        transposedShape.push_back(indexContiguous.size(i));
    }
    transposedShape.push_back(K);

    auto outputReshaped = outputTransposed.reshape(transposedShape);
    auto outputContiguous = outputReshaped.transpose(ndim - 1, dimVal).contiguous();

    return outputContiguous.reshape(index.sizes());
}

}  // namespace ascend_kernel
