92	// =========================== Init ============================
93	
94	template<typename T>
95	__aicore__ inline void GatherKernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
96	                                                int64_t inputRows, int64_t srcDimSize,
97	                                                int64_t indexSize, int64_t totalRows,
98	                                                int64_t rowOffset) {
99	    inputRows_ = inputRows;
100	    srcDimSize_ = srcDimSize;
101	    indexSize_ = indexSize;
102	    totalRows_ = totalRows;
103	    rowOffset_ = rowOffset;
104	
105	    inputGm_.SetGlobalBuffer((__gm__ T*)input, inputRows * srcDimSize);
106	    indexGm_.SetGlobalBuffer((__gm__ int32_t*)index);
107	    outputGm_.SetGlobalBuffer((__gm__ T*)output);
108	
109	    // 32-byte aligned row bytes
110	    inputRowBytes_  = (srcDimSize * sizeof(T) + 31) / 32 * 32;
111	    indexRowBytes_  = (indexSize * sizeof(int32_t) + 31) / 32 * 32;
112	    outputRowBytes_ = (indexSize * sizeof(T) + 31) / 32 * 32;
113	
114	    int64_t perRowUB = inputRowBytes_ + indexRowBytes_ + outputRowBytes_;
115	
116	    if (perRowUB <= UB_CAPACITY && srcDimSize * sizeof(T) <= MAX_GATHER_SRC_BYTES
117	        && srcDimSize * sizeof(T) >= 32) {
118	        // Path 0: GatherPath - hardware Gather instruction
119	        path_ = 0;
120	        maxRowsPerBatch_ = UB_CAPACITY / perRowUB;
121	        if (maxRowsPerBatch_ < 1) maxRowsPerBatch_ = 1;
122	        pipe.InitBuffer(inputBuf_,  maxRowsPerBatch_ * inputRowBytes_);
123	        pipe.InitBuffer(indexBuf_,  maxRowsPerBatch_ * indexRowBytes_);
124	        pipe.InitBuffer(outputBuf_, maxRowsPerBatch_ * outputRowBytes_);
125	    } else if (perRowUB <= UB_CAPACITY) {
126	        // Path 1: UBPath - scalar UB access
127	        path_ = 1;
128	        pipe.InitBuffer(ubInputBuf_,  inputRowBytes_);
129	        pipe.InitBuffer(ubIndexBuf_,  indexRowBytes_);
130	        pipe.InitBuffer(ubOutputBuf_, outputRowBytes_);
131	    } else {
132	        // Path 2: ElementPath - element-wise GM direct access
133	        path_ = 2;
134	        pipe.InitBuffer(indexBufElem_,  indexRowBytes_);
135	        pipe.InitBuffer(outputBufElem_, outputRowBytes_);
136	    }
