141	template<typename T>
142	__aicore__ inline void GatherKernel<T>::ProcessGatherPath(int64_t startRow, int64_t numRows) {
143	    LocalTensor<T> inputLocal = inputBuf_.Get<T>();
144	    LocalTensor<int32_t> indexLocal = indexBuf_.Get<int32_t>();
145	    LocalTensor<T> outputLocal = outputBuf_.Get<T>();
146	
147	    // 1. Load input rows to UB
148	    DataCopyExtParams inputCopyParams;
149	    inputCopyParams.blockCount = 1;
150	    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
151	    inputCopyParams.srcStride = 0;
152	    inputCopyParams.dstStride = 0;
153	    DataCopyPadExtParams<T> inputPadParams;
154	    inputPadParams.isPad = false;
155	    for (int64_t r = 0; r < numRows; r++) {
156	        DataCopyPad(inputLocal[r * (inputRowBytes_ / sizeof(T))],
157	                    inputGm_[(startRow + r) * srcDimSize_], inputCopyParams, inputPadParams);
158	    }
159	    PipeBarrier<PIPE_ALL>();
160	
161	    // 2. Load index rows to UB (each row has independent index)
162	    DataCopyExtParams indexCopyParams;
163	    indexCopyParams.blockCount = 1;
164	    indexCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(int32_t));
165	    indexCopyParams.srcStride = 0;
166	    indexCopyParams.dstStride = 0;
167	    DataCopyPadExtParams<int32_t> indexPadParams;
168	    indexPadParams.isPad = false;
169	    for (int64_t r = 0; r < numRows; r++) {
170	        DataCopyPad(indexLocal[r * (indexRowBytes_ / sizeof(int32_t))],
171	                    indexGm_[(startRow + r) * indexSize_], indexCopyParams, indexPadParams);
172	    }
173	    PipeBarrier<PIPE_ALL>();
174	
175	    // 3. Muls: element index -> byte offset
176	    for (int64_t r = 0; r < numRows; r++) {
177	        int64_t off = r * (indexRowBytes_ / sizeof(int32_t));
178	        Muls(indexLocal[off], indexLocal[off], (int32_t)sizeof(T), indexSize_);
179	    }
180	    PipeBarrier<PIPE_ALL>();
181	
182	    // 4. ReinterpretCast + Gather
183	    LocalTensor<uint32_t> indexUintLocal = indexLocal.ReinterpretCast<uint32_t>();
184	    for (int64_t r = 0; r < numRows; r++) {
185	        int64_t inOff  = r * (inputRowBytes_ / sizeof(T));
186	        int64_t idxOff = r * (indexRowBytes_ / sizeof(uint32_t));
187	        int64_t outOff = r * (outputRowBytes_ / sizeof(T));
188	        Gather(outputLocal[outOff], inputLocal[inOff], indexUintLocal[idxOff],
189	               (uint32_t)0, static_cast<uint32_t>(indexSize_));
190	        PipeBarrier<PIPE_ALL>();
191	    }
192	
193	    // 5. Write output rows back to GM
194	    DataCopyExtParams outputCopyParams;
195	    outputCopyParams.blockCount = 1;
196	    outputCopyParams.blockLen = static_cast<uint32_t>(indexSize_ * sizeof(T));
197	    outputCopyParams.srcStride = 0;
198	    outputCopyParams.dstStride = 0;
199	    for (int64_t r = 0; r < numRows; r++) {
200	        DataCopyPad(outputGm_[(startRow + r) * indexSize_],
201	                    outputLocal[r * (outputRowBytes_ / sizeof(T))], outputCopyParams);
