208	template<typename T>
209	__aicore__ inline void GatherKernel<T>::ProcessUBPath(int64_t row) {
210	    LocalTensor<T> inputLocal = ubInputBuf_.Get<T>();
211	    LocalTensor<int32_t> indexLocal = ubIndexBuf_.Get<int32_t>();
212	    LocalTensor<T> outputLocal = ubOutputBuf_.Get<T>();
213	
214	    // Load input row
215	    DataCopyExtParams inputCopyParams;
216	    inputCopyParams.blockCount = 1;
217	    inputCopyParams.blockLen = static_cast<uint32_t>(srcDimSize_ * sizeof(T));
218	    inputCopyParams.srcStride = 0;
219	    inputCopyParams.dstStride = 0;
220	    DataCopyPadExtParams<T> inputPadParams;
221	    inputPadParams.isPad = false;
222	    DataCopyPad(inputLocal, inputGm_[row * srcDimSize_], inputCopyParams, inputPadParams);
223	    PipeBarrier<PIPE_ALL>();
224	
225	    // Load index row
226	    LoadIndexForRow(row, indexLocal);
227	
228	    // Scalar gather
229	    for (int64_t j = 0; j < indexSize_; j++) {
230	        int32_t idx = indexLocal.GetValue(j);
231	        T val = inputLocal.GetValue(idx);
232	        outputLocal.SetValue(j, val);
233	    }
234	    PipeBarrier<PIPE_ALL>();
235	
236	    // Write output
237	    WriteOutputForRow(row, outputLocal);
238	}
