242	template<typename T>
243	__aicore__ inline void GatherKernel<T>::ProcessElementPath(int64_t row) {
244	    LocalTensor<int32_t> indexLocal = indexBufElem_.Get<int32_t>();
245	    LocalTensor<T> outputLocal = outputBufElem_.Get<T>();
246	
247	    // Load index row
248	    LoadIndexForRow(row, indexLocal);
249	
250	    // Element-wise read from GM
251	    for (int64_t j = 0; j < indexSize_; j++) {
252	        int32_t idx = indexLocal.GetValue(j);
253	        T val = inputGm_.GetValue(row * srcDimSize_ + idx);
254	        outputLocal.SetValue(j, val);
255	    }
256	    PipeBarrier<PIPE_ALL>();
257	
258	    // Write output
259	    WriteOutputForRow(row, outputLocal);
260	}
261	
262	// =========================== Process ============================
263	
264	template<typename T>
265	__aicore__ inline void GatherKernel<T>::Process() {
266	    int64_t blockIdx_ = GetBlockIdx();
267	
268	    if (path_ == 0) {
269	        // GatherPath: continuous block assignment + multi-row batch processing
270	        int64_t blockDim = (totalRows_ < MAX_CORES) ? totalRows_ : MAX_CORES;
271	        int64_t base = totalRows_ / blockDim;
272	        int64_t remainder = totalRows_ % blockDim;
273	        int64_t myStart, myRows;
274	        if (blockIdx_ < remainder) {
275	            myStart = rowOffset_ + blockIdx_ * (base + 1);
276	            myRows = base + 1;
277	        } else {
278	            myStart = rowOffset_ + remainder * (base + 1) + (blockIdx_ - remainder) * base;
279	            myRows = base;
280	        }
281	
282	        for (int64_t r = myStart; r < myStart + myRows; r += maxRowsPerBatch_) {
283	            int64_t numRows = myStart + myRows - r;
284	            if (numRows > maxRowsPerBatch_) numRows = maxRowsPerBatch_;
285	            ProcessGatherPath(r, numRows);
286	        }
287	    } else {
288	        // UBPath / ElementPath: interleaved row assignment
289	        int64_t startRow = rowOffset_ + blockIdx_;
290	        for (int64_t r = startRow; r < rowOffset_ + totalRows_; r += MAX_CORES) {
291	            if (r >= inputRows_) break;
292	            if (path_ == 1) {
293	                ProcessUBPath(r);
294	            } else {
295	                ProcessElementPath(r);
296	            }
297	        }
298	    }
299	}
