301	// =========================== Kernel Entry ============================
302	
303	extern "C" __global__ __aicore__ void gather(GM_ADDR input, GM_ADDR index, GM_ADDR output,
304	                                                int64_t inputRows, int64_t srcDimSize,
305	                                                int64_t indexSize, int64_t dtypeSize,
306	                                                int64_t totalRows, int64_t rowOffset) {
307	    if (dtypeSize == 4) {
308	        GatherKernel<float> op;
309	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
310	        op.Process();
311	    } else if (dtypeSize == 2) {
312	        // fp16 and bf16 are both 2 bytes, use half path for data movement
313	        GatherKernel<half> op;
314	        op.Init(input, index, output, inputRows, srcDimSize, indexSize, totalRows, rowOffset);
315	        op.Process();
316	    }
